{
  "findings": [
    {
      "check_id": "CKV_AZURE_123", 
      "title": "Role assignment lacks condition expression",
      "resource": "azurerm_role_assignment.negative8",
      "severity": "HIGH",
      "explanation": "The role assignment includes a condition_version but does not specify a condition. This can lead to overly permissive access as no conditional restrictions are applied to the role."
    }
  ],
  "patched_code": "resource \"azurerm_role_assignment\" \"negative8\" {\n  role_definition_id   = \"18d7d88d-d35e-4fb5-a5c3-7773c20a72d9\"\n  scope                = \"/subscriptions/12345678-1234-1234-1234-123456789abc\"\n  principal_id         = data.azurerm_client_config.current.object_id\n  principal_type       = \"ServicePrincipal\"\n  condition_version    = \"2.0\"\n  condition            = \"@Resource[\\\"Microsoft.Storage/storageAccounts/blobServices/containers\\\"].name == 'secure-container'\"\n}",
  "fix_summary": "Added a condition to the role assignment to restrict access to a specific resource, ensuring the condition_version is effectively utilized."
}
